'use client';

import { FormEvent, useState } from 'react';
type Obj = Record<string, any>;
const tabs = [{id:'overview',label:'Overview'},{id:'funding',label:'Funding'},{id:'leadership',label:'Leadership'},{id:'contacts',label:'Contacts & Social'},{id:'pricing',label:'Pricing & Fees'},{id:'geography',label:'Geography'},{id:'additional',label:'Additional'},{id:'evidence',label:'Sources & Gaps'}];
const val = (x:any):string => { const v=x && typeof x==='object' && 'value' in x ? x.value : x; if(v===null||v===undefined||v==='') return 'Not found'; if(typeof v==='boolean') return v?'Yes':'No'; if(Array.isArray(v)) return v.length?v.join(', '):'Not found'; if(typeof v==='number') return v.toLocaleString('en-US'); return String(v); };
function Card({label,field,wide=false}:{label:string;field:any;wide?:boolean}) {
 const v=field && typeof field==='object' && 'value' in field?field.value:field; const s=field?.status || (v==null||v===''?'not_found':'found');
 return <div className={'rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] p-4 min-w-0 '+(wide?'sm:col-span-2':'')}><div className="flex items-start justify-between gap-2"><span className="text-[10px] uppercase tracking-[.15em] font-bold text-[#81776B]">{label}</span><span className={'text-[9px] uppercase rounded-full px-2 py-1 font-bold '+(s==='found'?'bg-green-100 text-green-800':s==='partial'?'bg-amber-100 text-amber-800':s==='undisclosed'?'bg-purple-100 text-purple-800':'bg-[#F1ECE5] text-[#746A5F]')}>{s.replace('_',' ')}</span></div><div className={'mt-2 text-sm font-semibold break-words '+(v==null||v===''?'text-[#9B9185] font-normal':'text-[#25211D]')}>{val(v)}</div>{field?.note&&<p className="mt-2 text-[11px] leading-relaxed text-[#82786C]">{field.note}</p>}{field?.evidence?.length>0&&<div className="mt-3 flex flex-wrap gap-2">{field.evidence.slice(0,3).map((e:any,i:number)=><a key={i} href={e.sourceUrl} target="_blank" rel="noreferrer" className="text-[10px] underline text-[#B94B24]">Source {i+1} ↗</a>)}</div>}</div>;
}
function Heading({n,title,desc}:{n:string;title:string;desc:string}) { return <div className="mb-4"><div className="text-[10px] uppercase tracking-[.18em] font-bold text-[#C65A2D]">{n}</div><h2 className="mt-1 text-xl font-extrabold">{title}</h2><p className="mt-1 text-xs text-[#7A7064]">{desc}</p></div>; }
export default function ExternalPage() {
 const [name,setName]=useState(''); const [url,setUrl]=useState(''); const [report,setReport]=useState<Obj|null>(null); const [loading,setLoading]=useState(false); const [error,setError]=useState(''); const [tab,setTab]=useState('overview'); const [progress,setProgress]=useState('Preparing research…'); const [json,setJson]=useState(false);
 async function submit(e:FormEvent) { e.preventDefault(); if(!name.trim()&&!url.trim()){setError('Enter a company name, website URL, or both.');return;} setLoading(true);setError('');setReport(null);setTab('overview');setProgress('Discovering public pages…'); let i=0; const labels=['Discovering public pages…','Scraping relevant sources…','Extracting company intelligence…','Normalizing funding to USD…','Organizing evidence and missing fields…']; const timer=window.setInterval(()=>{i=Math.min(i+1,labels.length-1);setProgress(labels[i]);},3000); try {const r=await fetch('/api/external',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({companyName:name.trim()||undefined,url:url.trim()||undefined})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Research failed.');setReport(d);setProgress('Research complete');}catch(e:any){setError(e.message||'Research failed.');setProgress('Research stopped');}finally{window.clearInterval(timer);setLoading(false);} }
 function download(){if(!report)return;const b=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download='external-company-report.json';a.click();URL.revokeObjectURL(u);}
 const c=report?.company||{}, f=report?.funding||{};
 const count=report?Object.values({company:c,funding:f,pricing:report.pricing,contacts:report.contacts,social:report.social,geography:report.geography,additional:report.additional}).reduce((n:number,section:any)=>n+Object.values(section||{}).filter((x:any)=>x&&typeof x==='object'&&'status' in x&&['found','partial'].includes(x.status)).length,0):0;
 return <main className="min-h-screen bg-[#FAF6EE] text-[#25211D]"><header className="sticky top-0 z-30 border-b border-[#DED5C7] bg-[#FAF6EE]/95 backdrop-blur px-4 sm:px-8"><div className="max-w-[1440px] mx-auto h-[68px] flex items-center justify-between gap-4"><a href="/" className="flex items-center gap-3"><div className="w-10 h-10 rounded-xl bg-[#FF6B35] border border-[#2C2724] flex items-center justify-center text-white text-xl font-black shadow-[2px_2px_0_#2C2724]">E</div><div><div className="font-extrabold">External <span className="text-[#C65A2D]">/</span></div><div className="text-[10px] text-[#807569]">HUNTLYST INTELLIGENCE</div></div></a><div className="flex items-center gap-3"><span className="hidden sm:inline text-[10px] uppercase tracking-wider font-bold text-[#6D6257]">● Research workspace</span><a href="/" className="text-xs font-bold border border-[#2C2724] rounded-xl px-3 py-2 bg-[#FFFDF9]">← Huntlyst</a></div></div></header>
 <div className="max-w-[1440px] mx-auto px-4 sm:px-8 py-8 sm:py-10"><div className="max-w-3xl mb-8"><div className="inline-flex items-center gap-2 border border-[#E6C5B4] bg-[#FFF0E8] text-[#A3431F] rounded-full px-3 py-1 text-[10px] uppercase tracking-[.15em] font-extrabold">✳ Agent 02 · External research</div><h1 className="mt-4 text-3xl sm:text-5xl font-extrabold tracking-[-.045em] leading-tight">One company. <span className="text-[#E76532]">Every public detail.</span></h1><p className="mt-4 text-sm sm:text-base leading-relaxed text-[#74695E] max-w-2xl">Enter a company name, its website, or both. External researches public sources, groups findings into clear sections, converts disclosed funding to USD where rates are available, and reports what could not be found.</p></div>
 <form onSubmit={submit} className="rounded-[24px] border-[1.5px] border-[#2C2724] bg-[#FFFDF9] p-4 sm:p-6 shadow-[4px_5px_0_#2C2724]"><div className="flex justify-between gap-3 mb-4"><div className="text-sm font-extrabold">Company research</div><div className="text-[10px] uppercase tracking-wider text-[#897E71]">Public sources</div></div><div className="grid md:grid-cols-[1fr_1.25fr_auto] gap-3 items-end"><label className="block"><span className="block text-[10px] uppercase tracking-wider font-bold text-[#766C60] mb-2">Company name <span className="normal-case font-normal">(optional)</span></span><input value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Blaze" className="w-full rounded-xl border border-[#D8CEBF] bg-white px-3.5 py-3 text-sm outline-none focus:border-[#FF6B35]"/></label><label className="block"><span className="block text-[10px] uppercase tracking-wider font-bold text-[#766C60] mb-2">Company website <span className="normal-case font-normal">(optional)</span></span><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://company.com" className="w-full rounded-xl border border-[#D8CEBF] bg-white px-3.5 py-3 text-sm outline-none focus:border-[#FF6B35]"/></label><button disabled={loading} className="h-[46px] px-5 rounded-xl bg-[#FF6B35] text-white font-extrabold text-sm border border-[#2C2724] shadow-[2px_3px_0_#2C2724] disabled:opacity-60 whitespace-nowrap">{loading?'Researching…':'↗ Research company'}</button></div><p className="mt-3 text-[11px] text-[#8B8074]">Either field is enough. If a name matches multiple companies, confirm the correct identity before trusting the result.</p>{loading&&<div className="mt-5 rounded-xl border border-[#F0D1C1] bg-[#FFF6F0] p-4"><div className="flex items-center gap-3"><div className="w-5 h-5 rounded-full border-2 border-[#F4C7B0] border-t-[#E76532] animate-spin"/><div><div className="text-xs font-extrabold">{progress}</div><div className="text-[10px] text-[#8C7567] mt-1">Searching, crawling and organizing evidence…</div></div></div><div className="mt-3 h-1.5 rounded-full bg-[#F2DCCF] overflow-hidden"><div className="h-full w-2/3 rounded-full bg-[#FF6B35] animate-pulse"/></div></div>}{error&&<div role="alert" className="mt-4 rounded-xl border border-red-300 bg-red-50 text-red-800 p-3 text-xs">{error}</div>}</form>
 {!report&&!loading&&<div className="grid sm:grid-cols-3 gap-3 mt-7">{[['01','Discover','Find relevant public company pages'],['02','Extract','Group identity, funding, people and pricing'],['03','Report gaps','Show unavailable fields instead of guessing']].map(x=><div key={x[0]} className="rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] p-4"><div className="text-[10px] font-mono text-[#D45D2C]">{x[0]} / EXTERNAL</div><div className="mt-2 font-extrabold text-sm">{x[1]}</div><div className="mt-1 text-xs text-[#82776B]">{x[2]}</div></div>)}</div>}
 {report&&<div className="mt-8"><div className="flex flex-col lg:flex-row lg:items-end justify-between gap-4 mb-5"><div><div className="text-[10px] uppercase tracking-[.18em] font-extrabold text-[#C65A2D]">Research dossier</div><h2 className="mt-1 text-2xl sm:text-3xl font-extrabold">{val(c.name)}</h2><p className="mt-1 text-xs text-[#81766A]">{val(c.website)} · {report.metadata?.pagesReviewed||0} pages reviewed · {new Date(report.metadata?.researchedAt||Date.now()).toLocaleString()}</p></div><div className="flex flex-wrap gap-2"><div className="rounded-xl border bg-white border-[#E4DCCF] px-3 py-2 text-xs"><b>{count}</b> fields found</div><div className="rounded-xl border bg-white border-[#E4DCCF] px-3 py-2 text-xs"><b>{report.missingFields?.length||0}</b> gaps</div><button type="button" onClick={download} className="rounded-xl border border-[#2C2724] bg-[#FFFDF9] px-3 py-2 text-xs font-bold">↓ Export JSON</button><button type="button" onClick={()=>setJson(!json)} className="rounded-xl border border-[#2C2724] bg-[#FFFDF9] px-3 py-2 text-xs font-bold">{json?'Hide JSON':'View JSON'}</button></div></div>
 <div className="grid lg:grid-cols-[220px_minmax(0,1fr)] gap-5 items-start"><nav className="rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] p-2 grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-1 gap-1">{tabs.map(t=><button key={t.id} type="button" onClick={()=>setTab(t.id)} className={'text-left rounded-xl px-3 py-2.5 text-xs font-bold '+(tab===t.id?'bg-[#FFE7DC] text-[#B94920]':'text-[#766C60] hover:bg-[#F8F2E9]')}>{t.label}</button>)}</nav><div className="min-w-0">
 {tab==='overview'&&<><Heading n="01 / Company profile" title="Company overview" desc="Core identity, age, business type and products."/><div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-3"><Card label="Company name" field={c.name}/><Card label="Website" field={c.website}/><Card label="Company age" field={c.companyAge}/><Card label="Company type" field={c.companyType}/><Card label="Sector" field={c.sector}/><Card label="Industry" field={c.industry}/><Card label="Founded" field={c.foundedDate}/><Card label="Headquarters" field={c.headquarters}/><Card label="Employees" field={c.employeeCount}/><Card label="Description" field={c.description} wide/><Card label="Products & services" field={c.productsServices} wide/><Card label="Operating locations" field={c.operatingLocations} wide/></div></>}
 {tab==='funding'&&<><Heading n="02 / Capital" title="Funding intelligence" desc="Disclosed rounds, stages and investors, normalized to USD where possible."/><div className="grid sm:grid-cols-2 gap-3 mb-4"><Card label="Total disclosed funding (USD)" field={f.totalFundingDisplay}/><Card label="Latest stage" field={f.latestStage}/><Card label="Latest round" field={f.latestRound}/><Card label="Investors" field={f.investors}/><Card label="Valuation (USD)" field={f.valuationUsd}/><Card label="Revenue" field={f.revenue}/></div><div className="rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] overflow-hidden"><div className="p-4 border-b border-[#E4DCCF] font-extrabold text-sm">Funding rounds</div>{f.rounds?.length?f.rounds.map((r:any,i:number)=><div key={i} className="p-4 border-b border-[#EDE5DA] grid sm:grid-cols-[1fr_auto] gap-3"><div><b className="text-sm">{r.name}</b><div className="text-xs text-[#81766A] mt-1">{r.date||'Date not found'} · {r.investors?.join(', ')||'Investors not found'}</div><div className="text-[10px] text-[#8C8074] mt-2">Original: {r.originalAmount==null?'Not found':r.originalAmount.toLocaleString()+' '+(r.originalCurrency||'')} · FX date: {r.conversionDate||'Unavailable'} · {r.status}</div>{r.sourceUrl&&<a className="inline-block mt-2 text-[10px] text-[#B94920] underline" href={r.sourceUrl} target="_blank" rel="noreferrer">Source ↗</a>}</div><b className="text-lg text-[#C65A2D]">{r.amountUsd==null?'USD n/a':'$'+(r.amountUsd>=1e6?(r.amountUsd/1e6).toFixed(2)+'M':r.amountUsd.toLocaleString())}</b></div>):<p className="p-5 text-sm text-[#8B8074]">No individual rounds found in reviewed public sources.</p>}</div></>}
 {tab==='leadership'&&<><Heading n="03 / People" title="Leadership & founders" desc="Publicly supported people and roles."/><div className="grid md:grid-cols-2 gap-3">{report.leadership?.length?report.leadership.map((x:any,i:number)=><div key={i} className="rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] p-4"><b>{x.name}</b><div className="text-xs text-[#7E7367] mt-1">{x.role||'Role not found'}</div>{x.bio&&<p className="mt-3 text-xs leading-relaxed text-[#655B51]">{x.bio}</p>}<div className="mt-3 flex flex-wrap gap-3 text-xs">{x.linkedin&&<a className="underline text-[#B94920]" href={x.linkedin} target="_blank" rel="noreferrer">LinkedIn ↗</a>}{x.email&&<a className="underline text-[#B94920]" href={'mailto:'+x.email}>{x.email}</a>}{x.sourceUrl&&<a className="underline text-[#B94920]" href={x.sourceUrl} target="_blank" rel="noreferrer">Source ↗</a>}</div></div>):<p className="text-sm text-[#8B8074]">No leadership profiles found in reviewed sources.</p>}</div></>}
 {tab==='contacts'&&<><Heading n="04 / Reach" title="Contacts & social" desc="Public contact details and official profiles."/><div className="grid sm:grid-cols-2 gap-3"><Card label="Company email" field={report.contacts.companyEmail}/><Card label="Phone" field={report.contacts.phone}/><Card label="Contact page" field={report.contacts.contactPage}/><Card label="Public emails" field={report.contacts.publicEmails}/><Card label="Company LinkedIn" field={report.social.companyLinkedin}/><Card label="X profile" field={report.social.x}/><Card label="Other profiles" field={report.social.otherProfiles} wide/></div></>}
 {tab==='pricing'&&<><Heading n="05 / Commercial" title="Pricing & fees" desc="Public pricing, subscription plans, fees or quote-based models."/><div className="grid sm:grid-cols-2 gap-3"><Card label="Pricing model" field={report.pricing.pricingModel}/><Card label="Fees / pricing" field={report.pricing.fees} wide/><Card label="Plans" field={report.pricing.plans} wide/><Card label="Pricing page" field={report.pricing.pricingUrl} wide/></div></>}
 {tab==='geography'&&<><Heading n="06 / Footprint" title="Geography & presence" desc="Office footprint is separate from customer-market presence."/><div className="grid sm:grid-cols-2 gap-3"><Card label="Headquarters country" field={report.geography.headquartersCountry}/><Card label="US office presence" field={report.geography.usOfficePresence}/><Card label="US customer presence" field={report.geography.usCustomerPresence}/><Card label="Operating countries" field={report.geography.countries} wide/></div></>}
 {tab==='additional'&&<><Heading n="07 / Signals" title="Additional intelligence" desc="News, partnerships, hiring and acquisitions."/><div className="grid sm:grid-cols-2 gap-3"><Card label="Recent news" field={report.additional.recentNews} wide/><Card label="Partnerships" field={report.additional.partnerships} wide/><Card label="Hiring" field={report.additional.hiring} wide/><Card label="Acquisitions" field={report.additional.acquisitions} wide/></div></>}
 {tab==='evidence'&&<><Heading n="08 / Audit" title="Sources & missing information" desc="Not found does not automatically mean private or undisclosed."/><div className="rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] p-4 mb-4"><b className="text-sm">Research status: {report.metadata?.researchStatus||'partial'}</b><p className="text-xs mt-2 text-[#7D7266]">{report.metadata?.currencyNote}</p><p className="text-xs mt-2 text-[#7D7266]">{report.metadata?.pagesReviewed||0} pages · {report.metadata?.researchedAt}</p></div><div className="rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] p-4 mb-4"><b className="text-sm">Missing fields ({report.missingFields?.length||0})</b>{report.missingFields?.length?report.missingFields.map((m:any,i:number)=><div key={i} className="mt-3 border-b border-[#F0E9DF] pb-3 text-xs"><b>{m.field}</b><p className="mt-1 text-[#84796D]">{m.explanation}</p><span className="inline-block mt-2 rounded-full bg-[#F1ECE5] px-2 py-1 text-[9px] uppercase">{m.status}</span></div>):<p className="mt-2 text-xs">No fields marked missing.</p>}</div><div className="rounded-2xl border border-[#E4DCCF] bg-[#FFFDF9] p-4 mb-4"><b className="text-sm">Source pages ({report.evidence?.length||0})</b>{report.evidence?.map((e:any,i:number)=><div key={i} className="mt-3 border-b border-[#F0E9DF] pb-3 text-xs"><a href={e.sourceUrl} target="_blank" rel="noreferrer" className="font-bold text-[#B94920] underline break-all">{e.sourceTitle||e.sourceUrl}</a><div className="mt-1 text-[#8A7F73] break-all">{e.sourceUrl}</div><p className="mt-2 text-[#6D6257]">{e.excerpt}</p></div>)}</div>{report.conflicts?.length>0&&<div className="rounded-2xl border border-[#E9C9A0] bg-[#FFF8EC] p-4"><b className="text-sm">Conflicting claims</b>{report.conflicts.map((x:any,i:number)=><p key={i} className="mt-3 text-xs"><b>{x.field}</b>: {x.claims?.join(' / ')}</p>)}</div>}</>}
 </div></div>{json&&<pre className="mt-5 max-h-[480px] overflow-auto rounded-2xl bg-[#211F1C] text-[#F7EDE0] p-4 text-[11px]">{JSON.stringify(report,null,2)}</pre>}</div>}
 <footer className="mt-12 border-t border-[#E4DCCF] pt-5 flex flex-col sm:flex-row justify-between gap-2 text-[10px] text-[#95897B]"><span>EXTERNAL · HUNTLYST COMPANY INTELLIGENCE</span><span>Evidence first. Unknown is better than invented.</span></footer></div></main>;
}
